(() => {const dialog=document.getElementById('watch-slide-dialog');if(!dialog)return;document.querySelectorAll('.watch-slide-open').forEach(button=>button.addEventListener('click',()=>{const image=document.getElementById('watch-slide-large');image.src=button.dataset.slide;image.alt=button.querySelector('img').alt;document.getElementById('watch-slide-caption').textContent=button.dataset.caption;dialog.showModal();}));document.getElementById('watch-slide-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();}});})();
